/* eslint-disable space-in-parens */

import zeros = require( '@stdlib/ndarray/zeros' ); // eslint-disable-line import/no-unresolved
import rangeBy = require( './index' ); // eslint-disable-line import/no-unresolved


// TESTS //

// The function returns a number...
{
	const x = zeros( [ 10 ], {
		'dtype': 'float64'
	});

	function accessor( v: number ): number {
		return v * 2.0;
	}

	rangeBy( [ x, accessor ] ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not an array-like object containing an ndarray and a function...
{
	const x = zeros( [ 10 ], {
		'dtype': 'float64'
	});

	rangeBy( '10' ); // $ExpectError
	rangeBy( 10 ); // $ExpectError
	rangeBy( true ); // $ExpectError
	rangeBy( false ); // $ExpectError
	rangeBy( null ); // $ExpectError
	rangeBy( undefined ); // $ExpectError
	rangeBy( [] ); // $ExpectError
	rangeBy( [ x ] ); // $ExpectError
	rangeBy( {} ); // $ExpectError
	rangeBy( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 10 ], {
		'dtype': 'float64'
	});

	function accessor( v: number ): number {
		return v * 2.0;
	}

	rangeBy(); // $ExpectError
	rangeBy( [ x, accessor ], {} ); // $ExpectError
}
